const c = (title, first, steps, smaller, support, sourceIds = [], kind = 'study', note) => ({
  title, first, steps, smaller, support, sourceIds, kind,
  note: note || (kind === 'support' ? 'App-designed support navigation; qualified review pending.' : sourceIds.length ? 'Sources support the underlying principle. These exact steps and timings are app-designed.' : 'App-designed support navigation; qualified review pending.'),
});

