  'Exclusion': c('Find a place where you are included', 'Tell a trusted adult about the exclusion and ask for help finding a welcoming space.', ['Look for a supervised group around a shared interest.', 'Choose a small, optional way to join.', 'Report repeated harmful behavior rather than handling it alone.'], 'Ask which school group welcomes new members.', 'A counselor, teacher, or club sponsor', ['cdc-connection'], 'support'),
